4686	export const TINY_TRANSLATOR_JOURNEY_NAVIGATIONS = 6;
4687	
4688	/**
4689	 * The TinyTranslator specification, appended rather than woven in: it is the
4690	 * first application in the corpus that declares either opt-in mechanism, and
4691	 * keeping it whole is what lets a reader see the two declarations in one place.
4692	 */
4693	const angularTinyTranslatorSpec: AppSpec = {
4694		app: ANGULAR_TINY_TRANSLATOR_APP,
4695		framework: 'angular',
4696		/**
4697		 * The build record that pins the served migrated root, bound by the sha256 of
4698		 * its exact bytes: this record publishes a top-level `digest` over its own
4699		 * content rather than an `integrity.canonicalDigest`, so binding it by file
4700		 * bytes is the honest binding rather than a looser one.
4701		 *
4702		 * It is u19f, not u17d, because `dist-11` is u19f's root. u17d's `dist-7` is
4703		 * the green deterministic build whose artifact never bootstraps.
4704		 */
4705		canonicalReceipt:
4706			'evidence/runs/angular-tiny-translator-v0-12-0/u19f-localize-boot-green-lane.json',
4707		canonicalDigest: '46c8494c19e42cfeb19d9c47261be9b9182906d36aa3798e96e5adbedcd3dbc8',
4708		canonicalBinding: 'file-sha256',
4709		sources: {
4710			baseline: '.versionless/cache/angular-tiny-translator-v0-12-0-baseline/app/dist/rebuild-1',
4711			migrated: '.versionless/stage/angular-tiny-translator-v0-12-0-u17b/dist-11',
4712		},
