4717		mockedNonLoopbackSeams: WITNESS_ANGULAR_TINY_TRANSLATOR_SEAMS,
4718		renderedStyleProbes: WITNESS_ANGULAR_TINY_TRANSLATOR_STYLE_PROBES,
4719		// The two opt-ins. Everything the journey is allowed to hand the page, and
4720		// the only reason its context accepts a download at all.
4721		fileInputs: { root, surfaces: WITNESS_ANGULAR_TINY_TRANSLATOR_FILE_INPUT_SURFACES },
4722		downloads: 'capture',
