4724		journey: async (context, page, _transportEvidence, lifecycle) => {
4725			if (lifecycle.expectedServiceWorker !== null)
4726				throw new Error('TinyTranslator journey received a service-worker expectation');
4727			const checkpoints = [
4728				await refusedServiceWorkerCheckpoint(
4729					lifecycle,
4730					'before-interactions',
4731					TINY_TRANSLATOR_SERVICE_WORKER_ATTEMPT,
4732				),
4733			];
4734			const measuredRoutes: WitnessMeasuredScrollAbsence['routes'] = [];
4735			/**
4736			 * The generic scroll measurement, taken at every stage. The application
4737			 * pins its container to the viewport and gives the unit list and the
4738			 * editor pane their own overflow, so a stage that started overflowing
4739			 * fails here rather than passing silently unexercised.
4740			 */
4741			const measure = async (stage: string): Promise<void> => {
4742				const extents = await lifecycle.viewportScroll();
4743				if (
4744					extents.clientHeight !== TINY_TRANSLATOR_VIEWPORT.height ||
4745					extents.scrollHeight > extents.clientHeight ||
4746					extents.scrollY !== 0
4747				)
4748					throw new Error(
4749						`TinyTranslator stage overflows the viewport the receipt says it does not: ${stage} ${canonicalize(extents)}`,
4750					);
4751				measuredRoutes.push({
4752					route: stage,
4753					scrollHeight: extents.scrollHeight,
4754					clientHeight: extents.clientHeight,
4755				});
4756			};
4757			const storageKeys = async (): Promise<string[]> => {
4758				const keys = await lifecycle.browserStorageKeys();
4759				if (keys.sessionStorage.length !== 0)
4760					throw new Error(
4761						`TinyTranslator wrote session storage the receipt says it does not: ${canonicalize(keys.sessionStorage)}`,
4762					);
4763				return tinyTranslatorStorageKeys(keys.localStorage);
4764			};
4765			await page.trackEvents('click', 'input', 'change', 'keydown');
4766	
4767			// (a) The empty application, on its own home route, before anything has
4768			// been handed to it.
4769			await context.expect.page.text(page, TT_APP_TITLE, 'Tiny Translator');
4770			await context.expect.page.bodyText(page, {
4771				contains: 'Currently there is no open project.',
4772			});
