4774			await measure(TINY_TRANSLATOR_HOME_ROUTE);
4775	
4776			// (b) A genuine hover on the toolbar's project control, for the tooltip
4777			// the application renders into its own overlay.
4778			await page.hover(TT_EDIT_PROJECT_LINK);
4779			await context.expect.page.text(
4780				page,
4781				TT_TOOLTIP,
4782				'Details of the project (click to open)',
4783			);
