4795			// the string off the page and this assertion goes red on it.
4796			await context.expect.page.exists(page, TT_UPLOAD_LABEL);
4797			await context.expect.page.bodyText(page, { contains: TINY_TRANSLATOR_MUTATION_SEAM });
4798			const renderedStyles = await lifecycle.renderedStyles();
