4805			if (resolvedFontFamily === undefined || resolvedFontFamily.length === 0)
4806				throw new Error('TinyTranslator icon probe resolved no font family');
4807			await measure(TINY_TRANSLATOR_CREATE_ROUTE);
4808	
4809			// (d) The project the journey creates through the application's own
4810			// form, with the synthetic translation file handed to the real hidden
4811			// file input. This load is the parity arbitration itself: the migrated
4812			// lane inserted a `typeof` guard into the FileReader service, and
