},
bodyText: async (page, expectation, waitOptions) => {
	const conditions = [];
	const requirements = [];
	if (expectation.contains !== void 0) {
		conditions.push(`(document.body?.textContent ?? '').includes(${JSON.stringify(expectation.contains)})`);
		requirements.push(`contain ${JSON.stringify(expectation.contains)}`);
	}
	if (expectation.notContains !== void 0) {
		conditions.push(`!(document.body?.textContent ?? '').includes(${JSON.stringify(expectation.notContains)})`);
		requirements.push(`stop containing ${JSON.stringify(expectation.notContains)}`);
	}
	if (conditions.length === 0) failAssertion("page.bodyText", null, null, "expect.page.bodyText needs a contains and/or notContains expectation.");
	await expectPageCondition({
		assertion: "page.bodyText",
		page,
		condition: conditions.join(" && "),
		timeoutMs: waitOptions?.timeoutMs ?? defaultTimeoutMs,
		describeFailure: async () => `expected the page body text to ${requirements.join(" and ")}, but it never did`
	});
},
attribute: async (page, selector, attributeName, expected, waitOptions) => {
	const element = selectorExpression(selector);
	const attributeValue = `${element}?.getAttribute(${JSON.stringify(attributeName)})`;
	await expectPageCondition({
		assertion: "page.attribute",
		page,
		condition: expected === null ? `(() => { const el = ${element}; return el !== null && !el.hasAttribute(${JSON.stringify(attributeName)}); })()` : expected === void 0 ? `(${attributeValue}) !== null && (${attributeValue}) !== undefined` : `(${attributeValue}) === ${JSON.stringify(expected)}`,
		timeoutMs: waitOptions?.timeoutMs ?? defaultTimeoutMs,
		describeFailure: async () => {
			const actual = await readPageState(page, `(() => { const el = ${element}; return el === null ? { missing: true } : { value: el.getAttribute(${JSON.stringify(attributeName)}) }; })()`);
			if (actual?.missing === true) return `expected '${selector}' to ${expected === null ? `exist without attribute '${attributeName}'` : `have attribute '${attributeName}'`}, but no element matched the selector`;
